--
-- Hər UPDATE dəyişdirdiyi dəyəri WHERE-də təsdiq edir: skript ikinci dəfə işlədiləndə heç nə dəyişmir.
-- Hamısı bir tranzaksiyadadır; yoxlama uyğun gəlməsə, hər şey geri qaytarılır.

\set ON_ERROR_STOP on
BEGIN;

CREATE TEMP TABLE before_state ON COMMIT DROP AS
SELECT count(*) AS lines, sum("Quantity" * "UnitPrice") AS known_amount,
       count(*) FILTER (WHERE "OrderLineType" = 'Monthly') AS monthly,
       count(*) FILTER (WHERE "OrderLineType" = 'OutsideMonthly') AS outside
  FROM "OrderRequestItems";

-- № 38 · sətir 886 · location: 'Heydər Əliyev Mərkəzi' -> 'Parlament parkı'
UPDATE "OrderRequestItems" SET "OrderRequestId" = (SELECT r."Id" FROM "OrderRequests" r JOIN "Locations" l ON l."Id" = r."LocationId" WHERE l."Name" = 'Parlament parkı' AND r."RequestPeriod" = DATE '2026-04-01')
  WHERE "Id" = 886 AND "OrderRequestId" = 36;
INSERT INTO "OrderRequestEditEvents" ("OrderRequestId","Action","OrderRequestItemId","ProductVariantId","Field","OldValue","NewValue","ActorUserId","ActorDisplayName","OccurredAtUtc") SELECT i."OrderRequestId", 'ItemMovedToAnotherLocation', i."Id", i."ProductVariantId", NULL, 'Heydər Əliyev Mərkəzi', 'Parlament parkı', 'fa7aeed2-288d-4b36-b2f7-d581e465e464', 'Administrator (Excel ilə uzlaşdırma 2026-10-09)', now() FROM "OrderRequestItems" i WHERE i."Id" = 886 AND i."OrderRequestId" <> 36 AND NOT EXISTS (SELECT 1 FROM "OrderRequestEditEvents" e WHERE e."OrderRequestItemId" = i."Id" AND e."Action" = 'ItemMovedToAnotherLocation' AND e."OldValue" IS NOT DISTINCT FROM 'Heydər Əliyev Mərkəzi' AND e."NewValue" IS NOT DISTINCT FROM 'Parlament parkı');

