-- Yoxlama: heç bir sətir itməməli, yaranmamalı və sahibsiz qalmamalıdır.
DO $$
DECLARE was bigint; now_ bigint; orphans bigint;
BEGIN
  SELECT lines INTO was FROM before_state;
  SELECT count(*) INTO now_ FROM "OrderRequestItems";
  IF was <> now_ THEN RAISE EXCEPTION 'sətir sayı dəyişdi: % -> %', was, now_; END IF;
  SELECT count(*) INTO orphans FROM "OrderRequestItems" i LEFT JOIN "OrderRequests" r ON r."Id" = i."OrderRequestId" WHERE r."Id" IS NULL;
  IF orphans > 0 THEN RAISE EXCEPTION 'sahibsiz sətir: %', orphans; END IF;
END $$;

SELECT 'before' AS state, lines, known_amount, monthly, outside FROM before_state
UNION ALL
SELECT 'after', count(*), sum("Quantity" * "UnitPrice"),
       count(*) FILTER (WHERE "OrderLineType" = 'Monthly'),
       count(*) FILTER (WHERE "OrderLineType" = 'OutsideMonthly')
  FROM "OrderRequestItems";

COMMIT;
